DROP TABLE IF EXISTS `dev_assist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dev_assist` (
  `experiment_id` int NOT NULL AUTO_INCREMENT,
  `seeds` int NOT NULL,
  `classifier` varchar(4000) COLLATE utf8mb3_bin NOT NULL,
  `cpus` int NOT NULL,
  `memory_max` int NOT NULL,
  `time_created` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `host` varchar(255) COLLATE utf8mb3_bin DEFAULT NULL,
  `executor` varchar(100) COLLATE utf8mb3_bin DEFAULT NULL,
  `time_started` timestamp NULL DEFAULT NULL,
  `automlClassifier` varchar(400) COLLATE utf8mb3_bin DEFAULT NULL,
  `info` varchar(1000) COLLATE utf8mb3_bin DEFAULT NULL,
  `avgPrecision` double DEFAULT NULL,
  `avgRecall` double DEFAULT NULL,
  `microPrecision` double DEFAULT NULL,
  `microRecall` double DEFAULT NULL,
  `avgMicroF1Measure` double DEFAULT NULL,
  `avgMacroF1MeasureLbl` double DEFAULT NULL,
  `avgMacroF1MeasureEx` double DEFAULT NULL,
  `lblPrecision` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblRecall` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblHarmonic` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `exception` text COLLATE utf8mb3_bin,
  `time_end` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`experiment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=611 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;
