  `time_started` timestamp NULL DEFAULT NULL,
  `classifierWeave` varchar(400) COLLATE utf8mb3_bin DEFAULT NULL,
  `datasetWeave` varchar(400) COLLATE utf8mb3_bin DEFAULT NULL,
  `info` varchar(1000) COLLATE utf8mb3_bin DEFAULT NULL,
