  `microPrecision` double DEFAULT NULL,
  `microRecall` double DEFAULT NULL,
  `avgMicroF1Measure` double DEFAULT NULL,
  `avgMacroF1MeasureLbl` double DEFAULT NULL,
  `avgMacroF1MeasureEx` double DEFAULT NULL,
  `lblPrecision` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblRecall` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblHarmonic` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblTruePositive` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblFalsePositive` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
