  `lblTrueNegative` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `microFMeasure` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `lblFalseNegative` varchar(500) COLLATE utf8mb3_bin DEFAULT NULL,
  `exception` text COLLATE utf8mb3_bin,
  `time_end` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`experiment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2100 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;
